B.avA=new A.a("\u0641\u062f\u0639\u0627 \u0628\u0647\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0645\u0633\u062d \u0628\u064a\u062f\u0647 \u0636\u0631\u0639\u0647\u0627\u060c \u0648\u0633\u0645\u0649 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644\u060c \u0648\u062f\u0639\u0627 \u0644\u0647\u0627 \u0641\u064a \u0634\u0627\u062a\u0647\u0627\u060c \u0641\u062a\u0641\u0627\u062c\u062a \u0639\u0644\u064a\u0647 -\u0641\u062a\u062d\u062a \u0645\u0627 \u0628\u064a\u0646 \u0631\u062c\u0644\u064a\u0647\u0627 \u0644\u0644\u062d\u0644\u0628\u060c \u0648\u062f\u0631\u062a -\u0623\u0631\u0633\u0644\u062a \u0627\u0644\u0644\u0628\u0646\u060c \u0648\u0627\u062c\u062a\u0631\u062a -\u0645\u0646 \u0627\u0644\u062c\u0631\u0629 \u0648\u0647\u064a \u0645\u0627 \u062a\u062e\u0631\u062c\u0647\u0627 \u0627\u0644\u0628\u0647\u064a\u0645\u0629 \u0645\u0646 \u0643\u0631\u0634\u0647\u0627 \u062a\u0645\u0636\u063a\u0647\u0627 \u060c \u0648\u062f\u0639\u0627 \u0628\u0625\u0646\u0627\u0621 \u064a\u064f\u0631\u0652\u0628\u0650\u0636 \u0627\u0644\u0631\u0647\u0637 -\u064a\u0631\u0648\u064a\u0647\u0645 \u062d\u062a\u0649 \u064a\u062b\u0642\u0644\u0648\u0627 \u0641\u064a\u0631\u0628\u0636\u0648\u0627 \u0623\u064a \u064a\u0642\u0639\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0644\u0644\u0646\u0648\u0645 \u0648\u0627\u0644\u0631\u0627\u062d\u0629\u060c \u0641\u062d\u0644\u0628 \u0641\u064a\u0647\u0627 \u062b\u062c\u0627 -\u0644\u0628\u0646\u0627 \u0643\u062b\u064a\u0631\u0627\u064b \u0633\u0627\u0626\u0644\u0627\u062d\u062a\u0649 \u0639\u0644\u0627\u0647 \u0627\u0644\u0628\u0647\u0627\u0621 -\u0623\u064a \u0623\u0639\u0644\u0627 \u0627\u0644\u0625\u0646\u0627\u0621 \u0628\u0647\u0627\u0621 \u0627\u0644\u0644\u0628\u0646\u060c \u062b\u0645 \u0633\u0642\u0627\u0647\u0627 \u062d\u062a\u0649 \u0631\u0648\u064a\u062a\u060c \u0648\u0633\u0642\u0649 \u0623\u0635\u062d\u0627\u0628\u0647 \u062d\u062a\u0649 \u0631\u0648\u0648\u0627\u060c \u0648\u0634\u0631\u0628 \u0622\u062e\u0631\u0647\u0645 \ufdfa \u062b\u0645 \u0623\u0631\u0627\u0636\u0648\u0627 -\u0623\u064a \u0631\u0648\u0648\u0627 \u0641\u0646\u0642\u0639\u0648\u0627 \u0628\u0627\u0644\u0631\u064a \u064a\u0631\u064a\u062f \u0634\u0631\u0628\u0648\u0627 \u0645\u0631\u0629 \u0628\u0639\u062f \u0645\u0631\u0629\u060c \u062b\u0645 \u062d\u0644\u0628 \u0641\u064a\u0647\u0627 \u062b\u0627\u0646\u064a\u0627\u064b \u0628\u0639\u062f \u0628\u062f\u0621 \u062d\u062a\u0649 \u0645\u0644\u0623 \u0627\u0644\u0625\u0646\u0627\u0621\u060c \u062b\u0645 \u063a\u0627\u062f\u0631\u0647 \u0639\u0646\u062f\u0647\u0627\u060c \u062b\u0645 \u0628\u0627\u064a\u0639\u0647\u0627\u060c \u0648\u0627\u0631\u062a\u062d\u0644\u0648\u0627 \u0639\u0646\u0647\u0627.",null)
B.aE8=new A.a("\u0648\u0642\u062f \u0631\u0648\u064a \u0641\u0649 \u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0623\u0645 \u0645\u0639\u0628\u062f \u0623\u0646\u0647\u0627 \u0643\u062b\u0631\u062a \u063a\u0646\u0645\u0647\u0627\u060c \u0648\u0646\u0645\u062a \u062d\u062a\u0649 \u062c\u0644\u0628\u062a \u0645\u0646\u0647\u0627 \u062c\u0644\u0628\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0641\u0645\u0631 \u0623\u0628\u0648 \u0628\u0643\u0631\u060c \u0641\u0631\u0622\u0647 \u0627\u0628\u0646\u0647\u0627 \u0641\u0639\u0631\u0641\u0647\u060c \u0641\u0642\u0627\u0644: \u064a\u0627 \u0623\u0645\u0647 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0645\u0639 \u0627\u0644\u0645\u0628\u0627\u0631\u0643\u060c \u0641\u0642\u0627\u0645\u062a \u0625\u0644\u064a\u0647 \u0641\u0642\u0627\u0644\u062a: \u064a\u0627 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0645\u0639\u0643\u061f \u0642\u0627\u0644: \u0623\u0648 \u0645\u0627 \u062a\u062f\u0631\u064a\u0646 \u0645\u0646 \u0647\u0648\u061f \u0642\u0627\u0644\u062a: \u0644\u0627\u060c \u0642\u0627\u0644: \u0647\u0648 \u0646\u0628\u064a \u0627\u0644\u0644\u0647\u060c \u0641\u0623\u062f\u062e\u0644\u0647\u0627 \u0639\u0644\u064a\u0647\u060c \u0641\u0623\u0637\u0639\u0645\u0647\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0623\u0639\u0637\u0627\u0647\u0627. \u0648\u0641\u064a \u0631\u0648\u0627\u064a\u0629: \u0641\u0627\u0646\u0637\u0644\u0642\u062a \u0645\u0639\u064a \u0648\u0623\u0647\u062f\u062a \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0634\u064a\u0626\u0627\u064b \u0645\u0646 \u0623\u0642\u0637 \u0648\u0645\u062a\u0627\u0639 \u0627\u0644\u0623\u0639\u0631\u0627\u0628\u060c \u0641\u0643\u0633\u0627\u0647\u0627 \u0648\u0623\u0639\u0637\u0627\u0647\u0627\u060c \u0642\u0627\u0644: \u0648\u0644\u0627 \u0623\u0639\u0644\u0645\u0647 \u0625\u0644\u0627 \u0642\u0627\u0644: \u0648\u0623\u0633\u0644\u0645\u062a\u060c \u0648\u0630\u0643\u0631 \u0635\u0627\u062d\u0628 \u0627\u0644\u0648\u0641\u0627\u0621 \u0623\u0646\u0647\u0627 \u0647\u0627\u062c\u0631\u062a \u0647\u064a \u0648\u0632\u0648\u062c\u0647\u0627 \u0648\u0623\u0633\u0644\u0645 \u0623\u062e\u0648\u0647\u0627 \u062e\u0646\u064a\u0633 \u0648\u0627\u0633\u062a\u0634\u0647\u062f \u064a\u0648\u0645 \u0627\u0644\u0641\u062a\u062d.",null)
