B.aT9=new A.a("\u0627\u0646\u062f\u0644\u0639 \u0627\u0644\u0642\u062a\u0627\u0644 \u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0628\u0627\u0644\u0645\u0628\u0627\u0631\u0632\u0627\u062a \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0641\u062e\u0631\u062c \u0645\u0646 \u062c\u064a\u0634 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0639\u062a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u0648\u0623\u062e\u0648\u0647 \u0634\u064a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u0648\u0627\u0628\u0646\u0647 \u0627\u0644\u0648\u0644\u064a\u062f \u0648\u0637\u0644\u0628\u0648\u0627 \u0627\u0644\u0645\u0628\u0627\u0631\u0632\u0629\u060c \u0641\u062e\u0631\u062c \u0625\u0644\u064a\u0647\u0645 \u062b\u0644\u0627\u062b\u0629 \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0644\u0643\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0623\u0631\u062c\u0639\u0647\u0645 \u0644\u0623\u0646\u0647 \u0623\u062d\u0628\u0651\u064e \u0623\u0646 \u064a\u0628\u0627\u0631\u0632\u0647\u0645 \u0628\u0639\u0636 \u0623\u0647\u0644\u0647 \u0648\u0630\u0648\u064a \u0642\u0631\u0628\u0627\u0647 \u0648\u0644\u0630\u0644\u0643 \u0642\u0627\u0644 \ufdfa : \u0642\u0645 \u064a\u0627\u0639\u0628\u064a\u062f\u0629 \u0628\u0646 \u0627\u0644\u062d\u0627\u0631\u062b \u0648\u0642\u0645 \u064a\u0627\u062d\u0645\u0632\u0629 \u0648\u0642\u0645 \u064a\u0627 \u0639\u0644\u064a \u0648\u0628\u0627\u0631\u0632 \u062d\u0645\u0632\u0629 \u0634\u064a\u0628\u0629 \u0641\u0642\u062a\u0644\u0647 \u0648\u0628\u0627\u0631\u0632 \u0639\u0644\u064a \u0627\u0644\u0648\u0644\u064a\u062f \u0648\u0642\u062a\u0644\u0647 \u0648\u0628\u0627\u0631\u0632 \u0639\u0628\u064a\u062f\u0629 \u0628\u0646 \u0627\u0644\u062d\u0627\u0631\u062b \u0639\u062a\u0628\u0629 \u0641\u0636\u0631\u0628 \u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645\u0627 \u0627\u0644\u0622\u062e\u0631 \u0628\u0636\u0631\u0628\u0629 \u0645\u0648\u062c\u0639\u0629 \u060c \u0641\u0643\u0651\u0631 \u062d\u0645\u0632\u0629 \u0648\u0639\u0644\u064a \u0639\u0644\u0649 \u0639\u062a\u0628\u0629 \u0641\u0642\u062a\u0644\u0648\u0647 \u0648\u062d\u0645\u0644\u0627 \u0639\u0628\u064a\u062f\u0629 \u0648\u0623\u062a\u0628\u0627\u0639\u0647 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0644\u0643\u0646 \u0645\u0627\u0644\u0628\u062b \u0623\u0646 \u0627\u0633\u062a\u0634\u0647\u062f \u0645\u062a\u0623\u062b\u0631\u0627\u064b \u0628\u062c\u0631\u0627\u062d\u0647.",null)
B.av4=new A.a("\u0648\u0643\u0627\u0646 \u0634\u0639\u0627\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646: \u0623\u062d\u062f \u0623\u062d\u062f \u062b\u0645 \u0623\u0645\u0631\u0647\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0627\u0644\u0647\u062c\u0648\u0645 \u0627\u0644\u0645\u0636\u0627\u062f \u0645\u062d\u0631\u0636\u0627\u064b \u0644\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0642\u062a\u0627\u0644 \u0648\u0642\u0627\u0626\u0644\u0627\u064b \u0644\u0647\u0645 \u0634\u062f\u0648\u0627 \u0648\u0648\u0627\u0639\u062f\u0627\u064b \u0645\u0646 \u064a\u0642\u062a\u0644 \u0635\u0627\u0628\u0631\u0627\u064b \u0645\u062d\u062a\u0633\u0628\u0627\u064b \u0628\u0623\u0646 \u0644\u0647 \u0627\u0644\u062c\u0646\u0629 \u0648\u0645\u0645\u0627 \u0632\u0627\u062f \u0641\u064a \u0646\u0634\u0627\u0637 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0627\u0646\u062f\u0641\u0627\u0639\u0647\u0645 \u0641\u064a \u0627\u0644\u0642\u062a\u0627\u0644 \u0633\u0645\u0627\u0639\u0647\u0645 \u0642\u0648\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0633\u064e\u064a\u064f\u0647\u0652\u0632\u064e\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u064f \u0648\u064e\u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0627\u0644\u062f\u0651\u064f\u0628\u064f\u0631\u064e \u060c \u0648\u0639\u0644\u0645\u0647\u0645 \u0648\u0625\u062d\u0633\u0627\u0633\u0647\u0645 \u0628\u0625\u0645\u062f\u0627\u062f \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0648\u0628\u062a\u0642\u0644\u064a\u0644\u0647\u0645 \u0641\u064a \u0623\u0639\u064a\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0628\u0623\u0639\u064a\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646.",null)
