B.aBM=new A.a("\u062b\u0645 \u0623\u0631\u0633\u0644 \u0627\u0644\u0646\u062c\u0627\u0634\u064a \u0625\u0644\u0649 \u0623\u0635\u062d\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u062f\u0639\u0627\u0647\u0645\u060c \u0641\u0644\u0645\u0627 \u062c\u0627\u0621\u0647\u0645 \u0631\u0633\u0648\u0644\u0647 \u0627\u062c\u062a\u0645\u0639\u0648\u0627\u060c \u062b\u0645 \u0642\u0627\u0644 \u0628\u0639\u0636\u0647\u0645 \u0644\u0628\u0639\u0636 \u0645\u0627 \u062a\u0642\u0648\u0644\u0648\u0646 \u0644\u0644\u0631\u062c\u0644 \u0625\u0630\u0627 \u062c\u0626\u062a\u0645\u0648\u0647\u061f \u0642\u0627\u0644\u0648\u0627: \u0646\u0642\u0648\u0644 \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0639\u0644\u0645\u0646\u0627 \u0648\u0645\u0627 \u0623\u0645\u0631\u0646\u0627 \u0628\u0647 \u0646\u0628\u064a\u0651\u0646\u0627 \ufdfa \u0643\u0627\u0626\u0646\u064b\u0627 \u0641\u064a \u0630\u0644\u0643 \u0645\u0627 \u0647\u0648 \u0643\u0627\u0626\u0646\u060c \u0641\u0644\u0645\u0627 \u062c\u0627\u0621\u0647 \u0648\u0642\u062f \u062f\u0639\u0627 \u0627\u0644\u0646\u062c\u0627\u0634\u064a \u0623\u0633\u0627\u0642\u0641\u062a\u0647  \u0641\u0646\u0634\u0631\u0648\u0627 \u0645\u0635\u0627\u062d\u0641\u0647\u0645 - \u0623\u064a \u0623\u0646\u0627\u062c\u064a\u0644\u0647\u0645 \u0648\u0643\u0627\u0646\u0648\u0627 \u064a\u0633\u0645\u0648\u0646\u0647\u0627 \u0645\u0635\u0627\u062d\u0641- \u062d\u0648\u0644\u0647\u060c \u0633\u0623\u0644\u0647\u0645 \u0641\u0642\u0627\u0644: \u0645\u0627 \u0647\u0630\u0627 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u0630\u064a \u0641\u0627\u0631\u0642\u062a\u0645 \u0641\u064a\u0647 \u0642\u0648\u0645\u0643\u0645\u060c \u0648\u0644\u0645 \u062a\u062f\u062e\u0644\u0648\u0627 \u062f\u064a\u0646\u064a \u0648\u0644\u0627 \u062f\u064a\u0646 \u0623\u062d\u062f \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0645\u061f",null)
B.aPR=new A.a("\u0642\u0627\u0644\u062a \u0623\u0645 \u0633\u0644\u0645\u0629: \u0641\u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u0643\u0644\u0645\u0647 \u062c\u0639\u0641\u0631 \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 -\u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647- \u0641\u0642\u0627\u0644 \u0644\u0647: \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0644\u0643\u060c \u0643\u0646\u0627 \u0642\u0648\u0645\u064b\u0627 \u0623\u0647\u0644 \u062c\u0627\u0647\u0644\u064a\u0629\u060c \u0646\u0639\u0628\u062f \u0627\u0644\u0623\u0635\u0646\u0627\u0645\u060c \u0648\u0646\u0623\u0643\u0644 \u0627\u0644\u0645\u064a\u062a\u0629\u060c \u0648\u0646\u0623\u062a\u064a \u0627\u0644\u0641\u0648\u0627\u062d\u0634\u060c \u0648\u0646\u0642\u0637\u0639 \u0627\u0644\u0623\u0631\u062d\u0627\u0645\u060c \u0648\u0646\u0633\u064a\u0621 \u0627\u0644\u062c\u0648\u0627\u0631\u060c \u064a\u0623\u0643\u0644 \u0627\u0644\u0642\u0648\u064a \u0645\u0646\u0627 \u0627\u0644\u0636\u0639\u064a\u0641\u060c \u0641\u0643\u0646\u0627 \u0639\u0644\u0649 \u0630\u0644\u0643 \u062d\u062a\u0649 \u0628\u0639\u062b \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0646\u0627 \u0631\u0633\u0648\u0644\u0627\u064b \u0646\u0639\u0631\u0641 \u0646\u0633\u0628\u0647 \u0648\u0635\u062f\u0642\u0647\u060c \u0648\u0623\u0645\u0627\u0646\u062a\u0647 \u0648\u0639\u0641\u0627\u0641\u0647\u060c \u0641\u062f\u0639\u0627\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0644\u0646\u0648\u062d\u062f\u0647 \u0648\u0646\u0639\u0628\u062f\u0647\u060c \u0648\u0646\u062e\u0644\u0639 \u0645\u0627 \u0643\u0646\u0627 \u0646\u0639\u0628\u062f \u0648\u0622\u0628\u0627\u0624\u0646\u0627 \u0645\u0646 \u062f\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0648\u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0648\u0623\u0645\u0631\u0646\u0627 \u0628\u0635\u062f\u0642 \u0627\u0644\u062d\u062f\u064a\u062b\u060c \u0648\u0623\u062f\u0627\u0621 \u0627\u0644\u0623\u0645\u0627\u0646\u0629\u060c \u0648\u0635\u0644\u0629 \u0627\u0644\u0631\u062d\u0645\u060c \u0648\u062d\u0633\u0646 \u0627\u0644\u062c\u0648\u0627\u0631\u060c \u0648\u0627\u0644\u0643\u0641 \u0639\u0646 \u0627\u0644\u0645\u062d\u0627\u0631\u0645 \u0648\u0627\u0644\u062f\u0645\u0627\u0621 \u0648\u0646\u0647\u0627\u0646\u0627 \u0639\u0646 \u0627\u0644\u0641\u0648\u0627\u062d\u0634\u060c \u0648\u0642\u0648\u0644 \u0627\u0644\u0632\u0648\u0631\u060c \u0648\u0623\u0643\u0644 \u0645\u0627\u0644 \u0627\u0644\u064a\u062a\u064a\u0645\u060c \u0648\u0642\u0630\u0641 \u0627\u0644\u0645\u062d\u0635\u0646\u0629\u060c \u0648\u0623\u0645\u0631\u0646\u0627 \u0623\u0646 \u0646\u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0644\u0627 \u0646\u0634\u0631\u0643 \u0628\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0623\u0645\u0631\u0646\u0627 \u0628\u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0632\u0643\u0627\u0629 \u0648\u0627\u0644\u0635\u064a\u0627\u0645.",null)
B.axn=new A.a("\u0642\u0627\u0644\u062a: \u0641\u0639\u062f\u062f \u0639\u0644\u064a\u0647 \u0623\u0645\u0648\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.. \u0641\u0635\u062f\u0642\u0646\u0627\u0647 \u0648\u0622\u0645\u0646\u0627 \u0628\u0647\u060c \u0648\u0627\u062a\u0628\u0639\u0646\u0627\u0647 \u0639\u0644\u0649 \u0645\u0627 \u062c\u0627\u0621 \u0628\u0647. \u0641\u0639\u0628\u062f\u0646\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0641\u0644\u0645 \u0646\u0634\u0631\u0643 \u0628\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u062d\u0631\u0645\u0646\u0627 \u0645\u0627 \u062d\u0631\u0645 \u0639\u0644\u064a\u0646\u0627\u060c \u0648\u0623\u062d\u0644\u0644\u0646\u0627 \u0645\u0627 \u0623\u062d\u0644 \u0644\u0646\u0627\u060c \u0641\u0639\u062f\u0627 \u0639\u0644\u064a\u0646\u0627 \u0642\u0648\u0645\u0646\u0627\u060c \u0641\u0639\u0630\u0628\u0648\u0646\u0627 \u0648\u0641\u062a\u0646\u0648\u0646\u0627 \u0639\u0646 \u062f\u064a\u0646\u0646\u0627 \u0644\u064a\u0631\u062f\u0648\u0646\u0627 \u0625\u0644\u0649 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0645\u0646 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0646 \u0646\u0633\u062a\u062d\u0644 \u0645\u0627 \u0643\u0646\u0627 \u0646\u0633\u062a\u062d\u0644 \u0645\u0646 \u0627\u0644\u062e\u0628\u0627\u0626\u062b\u060c \u0641\u0644\u0645\u0627 \u0642\u0647\u0631\u0648\u0646\u0627 \u0648\u0638\u0644\u0645\u0648\u0646\u0627\u060c \u0648\u0634\u0642\u0651\u064e\u0648\u0627 \u0639\u0644\u064a\u0646\u0627\u060c \u0648\u062d\u0627\u0644\u0648\u0627 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646 \u062f\u064a\u0646\u0646\u0627\u060c \u062e\u0631\u062c\u0646\u0627 \u0625\u0644\u0649 \u0628\u0644\u062f\u0643\u060c \u0648\u0627\u062e\u062a\u0631\u0646\u0627\u0643 \u0639\u0644\u0649 \u0645\u0646 \u0633\u0648\u0627\u0643\u060c \u0648\u0631\u063a\u0628\u0646\u0627 \u0641\u064a \u062c\u0648\u0627\u0631\u0643\u060c \u0648\u0631\u062c\u0648\u0646\u0627 \u0623\u0644\u0627 \u0646\u0638\u0644\u0645 \u0639\u0646\u062f\u0643 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0644\u0643.",null)
B.aLb=new A.a("\u0642\u0627\u0644\u062a: \u0641\u0642\u0627\u0644 \u0644\u0647 \u0627\u0644\u0646\u062c\u0627\u0634\u064a: \u0647\u0644 \u0645\u0639\u0643 \u0645\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0634\u064a\u0621\u061f \u0642\u0627\u0644\u062a: \u0641\u0642\u0627\u0644 \u0644\u0647 \u062c\u0639\u0641\u0631: \u0646\u0639\u0645\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0627\u0644\u0646\u062c\u0627\u0634\u064a\u060c \u0641\u0627\u0642\u0631\u0623\u0647 \u0639\u0644\u064a\u0651\u064e\u061f",null)
