B.aSr=new A.a("\u0641\u0642\u062f \u0633\u0639\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0627\u0639\u062a\u0645\u0627\u062f \u0643\u0644 \u0637\u0627\u0642\u0627\u062a \u0627\u0644\u0623\u0645\u0629 \u0627\u0644\u0642\u0627\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0628\u0630\u0644 \u0648\u0627\u0644\u0639\u0637\u0627\u0621\u060c \u0631\u062c\u0627\u0644\u0627\u064b \u0648\u0646\u0633\u0627\u0621\u064b \u0648\u0635\u0628\u064a\u0627\u0646\u0627\u064b \u0648\u0634\u0628\u0627\u0628\u0627\u064b \u0648\u0634\u064a\u0648\u062e\u0627\u064b\u060c \u0648\u0625\u0644\u0649 \u0627\u0644\u062a\u0645\u0631\u0633 \u0639\u0644\u0649 \u0643\u0644 \u0645\u0647\u0627\u0631\u0629 \u0641\u064a \u0627\u0644\u0642\u062a\u0627\u0644 \u0637\u0639\u0646\u0627\u064b \u0628\u0627\u0644\u0631\u0645\u062d \u0648\u0636\u0631\u0628\u0627\u064b \u0628\u0627\u0644\u0633\u064a\u0641\u060c \u0648\u0631\u0645\u064a\u0627\u064b \u0628\u0627\u0644\u0646\u0628\u0644 \u0648\u0645\u0646\u0627\u0648\u0631\u0629 \u0639\u0644\u0649 \u0638\u0647\u0648\u0631 \u0627\u0644\u062e\u064a\u0644\u060c \u0648\u0643\u0627\u0646 \ufdfa \u064a\u0645\u0632\u062c \u062e\u0637\u0649 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0639\u0633\u0643\u0631\u064a\u0629 \u0627\u0644\u0645\u062a\u0648\u0627\u0632\u0646\u064a\u0646: \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0648\u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0648\u0627\u0644\u0623\u0645\u0644 \u0628\u0627\u0644\u0646\u0635\u0631 \u0623\u0648 \u0627\u0644\u062c\u0646\u0629 \u0648\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062c\u0647\u062f \u0641\u064a \u0633\u0627\u062d\u0627\u062a \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0648\u064a\u062d\u0636 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0644\u0649 \u0627\u062a\u0642\u0627\u0646 \u0645\u0627\u062a\u0639\u0644\u0645\u0648\u0627 \u0645\u0646 \u0641\u0646\u0648\u0646 \u0627\u0644\u0631\u0645\u0627\u064a\u0629 \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0645\u0646 \u062a\u0639\u0644\u0645 \u0627\u0644\u0631\u0645\u064a \u062b\u0645 \u062a\u0631\u0643\u0647 \u0641\u0644\u064a\u0633 \u0645\u0646\u0627\u060c \u0641\u0647\u064a \u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0639\u0645\u0648\u0645 \u0627\u0644\u0623\u0645\u0629 \u0648\u062d\u062a\u0649 \u0645\u0646 \u062f\u062e\u0644\u0648\u0627 \u0641\u064a \u0633\u0646 \u0627\u0644\u0634\u064a\u062e\u0648\u062e\u0629 \u0639\u0644\u0649 \u062f\u0631\u0628\u062a\u0647\u0645 \u0641\u064a \u0625\u0635\u0627\u0628\u0629 \u0627\u0644\u0647\u062f\u0641 \u0648\u0645\u0647\u0627\u0631\u0629 \u0627\u0644\u064a\u062f\u060c \u0648\u0646\u0634\u0627\u0637 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0625\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u064a\u0647\u062a\u0645 \u0628\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u0623\u0645\u0629 \u062c\u0645\u064a\u0639\u0647\u0627 \u0648\u064a\u0648\u062c\u0647\u0647\u0627 \u0646\u062d\u0648 \u0627\u0644\u0645\u0639\u0627\u0644\u064a \u0648\u0639\u0644\u0648 \u0627\u0644\u0647\u0645\u0629.",null)
B.aW4=new A.a("\u0625\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0648\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0646\u0628\u0648\u064a\u0629 \u0627\u0644\u0645\u0637\u0647\u0631\u0629 \u062a\u0639\u0644\u0645 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0639\u0644\u0649 \u0643\u0627\u0641\u0629 \u0627\u0644\u0623\u0635\u0639\u062f\u0629 \u0627\u0644\u0645\u0639\u0646\u0648\u064a\u0629 \u0648\u0627\u0644\u0645\u0627\u062f\u064a\u0629 \u0648\u0623\u0646 \u064a\u0623\u062e\u0630\u0648\u0627 \u062d\u0630\u0631\u0647\u0645 \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u064a\u064e\u0627\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627 \u062e\u064f\u0630\u064f\u0648\u0627 \u062d\u0650\u0630\u0652\u0631\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u062b\u064f\u0628\u064e\u0627\u062a\u064d \u0623\u064e\u0648\u0650 \u0627\u0646\u0652\u0641\u0650\u0631\u064f\u0648\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0633\u0627\u0621\u060c \u0648\u0647\u0630\u0627 \u064a\u062f\u0644 \u0639\u0644\u0649 \u0648\u062c\u0648\u0628 \u0627\u0644\u0639\u0646\u0627\u064a\u0629 \u0628\u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0648\u0627\u0644\u062d\u0630\u0631 \u0645\u0646 \u0645\u0643\u0627\u0626\u062f \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0648\u064a\u062f\u062e\u0644 \u0641\u064a \u0630\u0644\u0643 \u062c\u0645\u064a\u0639 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u062a\u0639\u0644\u0642\u0629 \u0628\u0627\u0644\u0623\u0633\u0644\u062d\u0629 \u0648\u0627\u0644\u0623\u0628\u062f\u0627\u0646 \u0648\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0639\u0644\u0649 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0623\u0633\u0644\u062d\u0629 \u0648\u0643\u064a\u0641\u064a\u0629 \u0627\u0633\u062a\u0639\u0645\u0627\u0644\u0647\u0627 \u0648\u062a\u0648\u062c\u064a\u0647\u0647\u0645 \u0625\u0644\u0649 \u0645\u0627\u064a\u0639\u064a\u0646\u0647\u0645 \u0639\u0644\u0649 \u062c\u0647\u0627\u062f \u0639\u062f\u0648\u0647\u0645 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0645\u0646 \u0645\u0643\u0627\u0626\u062f\u0647 \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u0648\u062c\u0644 \u0623\u0637\u0644\u0642 \u0627\u0644\u0623\u0645\u0631 \u0628\u0627\u0644\u0627\u0639\u062f\u0627\u062f \u0648\u0623\u062e\u0630 \u0627\u0644\u062d\u0630\u0631 \u0648\u0644\u0645 \u064a\u0630\u0643\u0631 \u0646\u0648\u0639\u0627\u064b \u062f\u0648\u0646 \u0646\u0648\u0639 \u0648\u0644\u0627 \u062d\u0627\u0644\u0627\u064b \u062f\u0648\u0646 \u062d\u0627\u0644\u060c \u0648\u0645\u0627\u0630\u0644\u0643 \u0625\u0644\u0627 \u0623\u0646 \u0627\u0644\u0623\u0648\u0642\u0627\u062a \u062a\u062e\u062a\u0644\u0641 \u0648\u0627\u0644\u0623\u0633\u0644\u062d\u0629 \u062a\u062a\u0646\u0648\u0639 \u0648\u0627\u0644\u0639\u062f\u0648 \u064a\u0642\u0644 \u0648\u064a\u0643\u062b\u0631 \u0648\u064a\u0636\u0639\u0641 \u0648\u064a\u0642\u0648\u0649.",null)
